import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.CLq81i8L.js";const m=JSON.parse('{"title":"Server Capabilities","description":"","frontmatter":{},"headers":[],"relativePath":"en/server/capabilities.md","filePath":"en/server/capabilities.md","lastUpdated":1785296213000}'),i={name:"en/server/capabilities.md"};function o(n,t,s,l,c,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="server-capabilities" tabindex="-1">Server Capabilities <a class="header-anchor" href="#server-capabilities" aria-label="Permalink to &quot;Server Capabilities&quot;">​</a></h1><blockquote><p>Last updated: 2026-06-28</p></blockquote><h2 id="_1-positioning" tabindex="-1">1. Positioning <a class="header-anchor" href="#_1-positioning" aria-label="Permalink to &quot;1. Positioning&quot;">​</a></h2><p><code>@server</code> is the backend API service of Schema Platform, providing a unified data and business-logic layer for the visual form designer, BPMN engine, and AI assistant.</p><h2 id="_2-tech-stack" tabindex="-1">2. Tech Stack <a class="header-anchor" href="#_2-tech-stack" aria-label="Permalink to &quot;2. Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Tech</th></tr></thead><tbody><tr><td>Runtime</td><td>Node.js + TypeScript (ESM)</td></tr><tr><td>Web framework</td><td>Koa.js</td></tr><tr><td>Database</td><td>MongoDB 8 (Mongoose ODM)</td></tr><tr><td>Auth</td><td>JWT + bcryptjs + OAuth2 authorization code</td></tr><tr><td>AI engine</td><td>LangGraph (multi-agent architecture)</td></tr><tr><td>Realtime</td><td>Socket.IO</td></tr><tr><td>Cache</td><td>Redis (optional)</td></tr><tr><td>Deploy</td><td>Traditional HTTP server (self-hosted)</td></tr></tbody></table><h2 id="_3-core-capability-matrix" tabindex="-1">3. Core Capability Matrix <a class="header-anchor" href="#_3-core-capability-matrix" aria-label="Permalink to &quot;3. Core Capability Matrix&quot;">​</a></h2><h3 id="_3-1-user-permission" tabindex="-1">3.1 User &amp; Permission <a class="header-anchor" href="#_3-1-user-permission" aria-label="Permalink to &quot;3.1 User &amp; Permission&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Multi-tenant isolation</td><td>AsyncLocalStorage + Mongoose plugin auto-injects tenantId</td><td>✅</td></tr><tr><td>RBAC permissions</td><td>Role-permission mapping, middleware validation, Redis cache (5min TTL)</td><td>✅</td></tr><tr><td>Data permission scope</td><td>all / dept / self / custom modes</td><td>✅</td></tr><tr><td>SSO</td><td>OAuth2 authorization code, cross-app session sharing</td><td>✅</td></tr><tr><td>API Key auth</td><td>Machine-to-machine calls, supports scopes and expiry</td><td>✅</td></tr><tr><td>JWT + API Key dual channel</td><td>apiOrJwtAuth middleware, flexible switching</td><td>✅</td></tr><tr><td>Audit log</td><td>Auto-records write ops, including body, IP, user</td><td>✅</td></tr><tr><td>Login log</td><td>Records login success/failure, supports clearing</td><td>✅</td></tr><tr><td>Online user management</td><td>Based on SSO sessions, supports force logout</td><td>✅</td></tr><tr><td>Password policy</td><td>Configurable password strength validation</td><td>✅</td></tr></tbody></table><h3 id="_3-2-organization" tabindex="-1">3.2 Organization <a class="header-anchor" href="#_3-2-organization" aria-label="Permalink to &quot;3.2 Organization&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Department management</td><td>Tree structure, supports move (with cycle detection)</td><td>✅</td></tr><tr><td>Position management</td><td>Position CRUD, supports sorting and status</td><td>✅</td></tr><tr><td>Menu management</td><td>Tree menu, supports frontend dynamic route generation</td><td>✅</td></tr><tr><td>User management</td><td>CRUD + batch import/export Excel</td><td>✅</td></tr><tr><td>Tenant management</td><td>Auto-initializes roles/admin/menus on creation</td><td>✅</td></tr></tbody></table><h3 id="_3-3-schema-management" tabindex="-1">3.3 Schema Management <a class="header-anchor" href="#_3-3-schema-management" aria-label="Permalink to &quot;3.3 Schema Management&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Schema CRUD</td><td>Create, edit, delete form schemas</td><td>✅</td></tr><tr><td>Version management</td><td>Auto-push version snapshots (up to 15), view/delete</td><td>✅</td></tr><tr><td>Publish mechanism</td><td>Draft -&gt; published, supports publishing a specific version</td><td>✅</td></tr><tr><td>Schema import</td><td>Deep validation of widget tree + ID regeneration</td><td>✅</td></tr><tr><td>Component templates</td><td>Template CRUD + apply (returns widgets with regenerated IDs)</td><td>✅</td></tr><tr><td>Mock data generation</td><td>Auto-generates mock form data from a schema</td><td>✅</td></tr></tbody></table><h3 id="_3-4-form-data" tabindex="-1">3.4 Form Data <a class="header-anchor" href="#_3-4-form-data" aria-label="Permalink to &quot;3.4 Form Data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Form submission</td><td>Submit data per schema</td><td>✅</td></tr><tr><td>Submission management</td><td>Paginated query, status filter, single/batch delete</td><td>✅</td></tr><tr><td>Approval flow</td><td>submitted -&gt; approved / rejected state transition</td><td>✅</td></tr><tr><td>Data export</td><td>CSV / Excel export</td><td>✅</td></tr><tr><td>Batch operations</td><td>Batch delete, batch update status</td><td>✅</td></tr></tbody></table><h3 id="_3-5-flow-engine" tabindex="-1">3.5 Flow Engine <a class="header-anchor" href="#_3-5-flow-engine" aria-label="Permalink to &quot;3.5 Flow Engine&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Flow definition</td><td>CRUD + publish + archive lifecycle</td><td>✅</td></tr><tr><td>Flow version</td><td>Versioned storage, supports coexistence of multiple versions</td><td>✅</td></tr><tr><td>Flow instance</td><td>Start, cancel, status query, flow graph retrieval</td><td>✅</td></tr><tr><td>Task management</td><td>Claim, complete, reject, reject-to-node, delegate</td><td>✅</td></tr><tr><td>Batch approval</td><td>Batch approve, batch reject, batch delegate</td><td>✅</td></tr><tr><td>Approval log</td><td>Full approval trail</td><td>✅</td></tr><tr><td>Flow notifications</td><td>Task create/timeout/complete/delegate/reject/flow-complete</td><td>✅</td></tr><tr><td>Flow templates</td><td>Built-in + custom templates, apply to create flows</td><td>✅</td></tr><tr><td>Flow monitoring</td><td>Overview, bottleneck analysis, trend analysis</td><td>✅</td></tr><tr><td>Intermediate events</td><td>Message events (send/receive/complete)</td><td>✅</td></tr><tr><td>Timers</td><td>Timer Intermediate Event, Cron trigger</td><td>✅</td></tr><tr><td>Data export</td><td>Approval log CSV/Excel export</td><td>✅</td></tr></tbody></table><h3 id="_3-6-ai-capabilities" tabindex="-1">3.6 AI Capabilities <a class="header-anchor" href="#_3-6-ai-capabilities" aria-label="Permalink to &quot;3.6 AI Capabilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Multi-agent chat</td><td>LangGraph-driven, Router -&gt; Editor/Flow/Page/General</td><td>✅</td></tr><tr><td>SSE streaming</td><td>thinking/text/tool_call/schema/flow/diff events</td><td>✅</td></tr><tr><td>HITL interrupt-resume</td><td>Pause on confirmation, resume after user confirms</td><td>✅</td></tr><tr><td>RAG semantic search</td><td>BGE-M3 vectors (SiliconFlow hosted) + cosine similarity + keyword fallback</td><td>✅</td></tr><tr><td>Multi LLM provider</td><td>DeepSeek/OpenAI/Claude/Ollama, with routing strategy</td><td>✅</td></tr><tr><td>LLM config priority</td><td>User request -&gt; tenant DB default -&gt; platform env -&gt; error guidance</td><td>✅</td></tr><tr><td>PLATFORM_LLM_ENABLED</td><td>Set false to disable platform-hosted LLM, allow DB config only</td><td>✅</td></tr><tr><td>MCP protocol</td><td>SSE transport, Schema/Flow/Widget MCP servers</td><td>✅</td></tr><tr><td>Version management</td><td>AI-generated content auto-versioned, supports diff and rollback</td><td>✅</td></tr><tr><td>Plugin marketplace</td><td>Plugin CRUD + install/uninstall</td><td>✅</td></tr><tr><td>Prompt management</td><td>Template CRUD + quality analysis + feedback optimization + testing</td><td>✅</td></tr><tr><td>Industry agents</td><td>Medical/finance/education industry templates</td><td>✅</td></tr><tr><td>Behavior learning</td><td>User behavior recording -&gt; preference analysis -&gt; personalized recommendation</td><td>✅</td></tr><tr><td>Schema-Flow sync</td><td>Schema updates auto-sync referencing Flow nodes</td><td>✅</td></tr><tr><td>@mention search</td><td>Search schema/flow/widget and reference</td><td>✅</td></tr><tr><td>Conversation export</td><td>Export as JSON</td><td>✅</td></tr><tr><td>AI monitoring</td><td>Agent performance stats, alerts, overview</td><td>✅</td></tr><tr><td>Message feedback</td><td>Positive/negative feedback, supports comments</td><td>✅</td></tr></tbody></table><h3 id="_3-7-integration-extension" tabindex="-1">3.7 Integration &amp; Extension <a class="header-anchor" href="#_3-7-integration-extension" aria-label="Permalink to &quot;3.7 Integration &amp; Extension&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Webhook</td><td>Event-driven, HMAC signature verification, auto-start flow</td><td>✅</td></tr><tr><td>Dictionary management</td><td>Dict types + data items, query by code</td><td>✅</td></tr><tr><td>System params</td><td>System/business params, query by key</td><td>✅</td></tr><tr><td>Micro-frontend apps</td><td>qiankun micro-app registration and management</td><td>✅</td></tr><tr><td>File upload</td><td>Image/avatar/general files, static file access</td><td>✅</td></tr><tr><td>Dashboard stats</td><td>Schema/Flow/AI/activity aggregate stats</td><td>✅</td></tr><tr><td>Event bus</td><td>schema.published / submission.created / webhook.triggered</td><td>✅</td></tr></tbody></table><h3 id="_3-8-infrastructure" tabindex="-1">3.8 Infrastructure <a class="header-anchor" href="#_3-8-infrastructure" aria-label="Permalink to &quot;3.8 Infrastructure&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Global error handling</td><td>errorHandler middleware, unified error response</td><td>✅</td></tr><tr><td>Request timeout</td><td>30s timeout, SSE endpoints auto-skip</td><td>✅</td></tr><tr><td>Request validation</td><td>Zod schema validation middleware</td><td>✅</td></tr><tr><td>CORS</td><td>Configurable cross-origin</td><td>✅</td></tr><tr><td>Helmet</td><td>Security headers</td><td>✅</td></tr><tr><td>Graceful shutdown</td><td>SIGTERM/SIGINT signal handling</td><td>✅</td></tr><tr><td>Redis cache</td><td>Optional cache layer, supports key-pattern deletion</td><td>✅</td></tr><tr><td>Structured logging</td><td>Unified log format</td><td>✅</td></tr><tr><td>DB seed</td><td>Permissions/roles/menus/admin/micro-apps/templates/OAuth clients</td><td>✅</td></tr><tr><td>DB migration</td><td>src/migrations/ directory, role migration scripts</td><td>✅</td></tr></tbody></table><h2 id="_4-known-todos" tabindex="-1">4. Known TODOs <a class="header-anchor" href="#_4-known-todos" aria-label="Permalink to &quot;4. Known TODOs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Current state</th><th>Note</th></tr></thead><tbody><tr><td><code>POST /api/ai/runtime/recommend-assignee</code></td><td>Rule-engine placeholder</td><td>Smart assignee recommendation pending AI</td></tr><tr><td><code>POST /api/ai/runtime/evaluate-condition</code></td><td>Returns fixed true</td><td>Condition expression evaluation pending</td></tr><tr><td><code>POST /api/ai/runtime/predict-outcome</code></td><td>Returns default</td><td>Approval outcome prediction pending</td></tr><tr><td><code>POST /api/ai/runtime/approval-suggestion</code></td><td>Returns generic advice</td><td>Approval suggestion pending</td></tr><tr><td>Online user / today&#39;s visit stats</td><td>Returns 0</td><td>Activity stats pending</td></tr></tbody></table><h2 id="_5-architecture-highlights" tabindex="-1">5. Architecture Highlights <a class="header-anchor" href="#_5-architecture-highlights" aria-label="Permalink to &quot;5. Architecture Highlights&quot;">​</a></h2><ol><li><strong>Clear layering</strong>: routes -&gt; middleware -&gt; models, well-separated responsibilities</li><li><strong>Native multi-tenancy</strong>: full-chain tenant isolation from middleware to model layer</li><li><strong>Event-driven</strong>: EventBus decouples schema publish, form submission, webhook trigger</li><li><strong>AI-First</strong>: LangGraph multi-agent architecture, supports streaming and human-in-the-loop</li><li><strong>ObjectId primary key</strong>: all models use MongoDB native ObjectId for consistent data references</li></ol>',27)])])}const u=e(i,[["render",o]]);export{m as __pageData,u as default};
